import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { doctorApi } from '../../api/doctorApi';
import Card from '../../components/Card';
import Loader from '../../components/Loader';
import ErrorBox from '../../components/ErrorBox';

const DoctorDashboard = () => {
  const navigate = useNavigate();
  const [appointments, setAppointments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const fetchAppointments = async () => {
    try {
      // Get all appointments, not just CONFIRMED
      const response = await doctorApi.getAppointments();
      if (response.success) {
        // Sort appointments by date (newest first) and then by time
        const sorted = response.appointments.sort((a, b) => {
          const dateA = new Date(a.appointmentDate);
          const dateB = new Date(b.appointmentDate);
          if (dateA.getTime() !== dateB.getTime()) {
            return dateB.getTime() - dateA.getTime(); // Newest first
          }
          // If same date, sort by time
          return (a.slotTime?.startTime || '').localeCompare(b.slotTime?.startTime || '');
        });
        setAppointments(sorted);
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to fetch appointments');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAppointments();
    // Refresh appointments every 30 seconds to see new bookings
    const interval = setInterval(fetchAppointments, 30000);
    return () => clearInterval(interval);
  }, []);

  if (loading) return <Loader />;

  return (
    <div className="p-6">
      <h1 className="text-3xl font-bold mb-6">Doctor Dashboard</h1>
      {error && <ErrorBox message={error} onClose={() => setError('')} />}

      <div className="mb-6">
        <h2 className="text-xl font-semibold mb-4">All Appointments</h2>
        {appointments.length > 0 ? (
          <div className="space-y-4">
            {appointments.map((appointment) => (
              <Card key={appointment._id}>
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="text-lg font-semibold mb-2">
                      {appointment.patient?.user?.name || 'N/A'}
                    </h3>
                    <p className="text-gray-600 mb-1">
                      <strong>Date:</strong> {new Date(appointment.appointmentDate).toLocaleDateString()}
                    </p>
                    <p className="text-gray-600 mb-1">
                      <strong>Time:</strong> {appointment.slotTime?.startTime} - {appointment.slotTime?.endTime}
                    </p>
                    <p className="text-gray-600 mb-1">
                      <strong>Reason:</strong> {appointment.reason}
                    </p>
                    <p className="text-gray-600 mb-1">
                      <strong>Status:</strong> <span className={`font-semibold ${
                        appointment.status === 'COMPLETED' ? 'text-green-600' :
                        appointment.status === 'CONFIRMED' ? 'text-blue-600' :
                        appointment.status === 'CANCELLED' ? 'text-red-600' : 'text-gray-600'
                      }`}>
                        {appointment.status}
                      </span>
                    </p>
                    <p className="text-gray-600">
                      <strong>Phone:</strong> {appointment.patient?.user?.phone || 'N/A'}
                    </p>
                  </div>
                  <button
                    onClick={() => navigate(`/doctor/appointment/${appointment._id}`)}
                    className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700"
                  >
                    View Details
                  </button>
                </div>
              </Card>
            ))}
          </div>
        ) : (
          <Card>
            <p className="text-center text-gray-600">No appointments found</p>
          </Card>
        )}
      </div>
    </div>
  );
};

export default DoctorDashboard;
